added=[e for e in CATALOG if e.get('fashion_history_reference') and e.get('history_track') in {t['id'] for t in TRACKS}]
assert len(added)==48
japan_orders={1,2,4,6,7,9,13,15}
regions=['south_asia','west_asia','southeast_asia','south_asia','west_asia','west_asia','west_asia','southeast_asia','africa','south_asia','africa','americas','americas','southeast_asia','south_asia','southeast_asia']
region_names={'south_asia':'南亚','west_asia':'西亚','southeast_asia':'东南亚','africa':'非洲地区选编','americas':'美洲地区选编'}
for e in added:
    e.update(added_in='39.0',fashion_history_extension=True)
    if e['history_track']=='japan_korea':
        japanese=e['history_order'] in japan_orders
        e['history_line']='japan' if japanese else 'korea';e['history_line_name']='日本女装路线' if japanese else '朝鲜半岛女装路线'
        e['aliases']+=['日本服饰','和服史','kimono history'] if japanese else ['韩服','hanbok','朝鲜服饰']
    elif e['history_track']=='regional':
        key=regions[e['history_order']-1];e['history_line']=key;e['history_line_name']=region_names[key];e['history_comparison_kind']='parallel'
        e['description']=e['description'].replace('演变观察：','区域对照：')
        e['note']='此组是不同地域与社群服装的并列选编，年代标明图例参考区间，不代表服装起源年代，也不构成国家或族群之间的演化链。人物、完整覆盖的内搭、配色和纹样均为原创示意；部分内层为保持覆盖而作调整，并非单件文物的精确复原。请结合相关阅读理解当地衣着、场景与称呼，勿以一套衣服代表整个地区。'
